From 74c691ddaf1b8c1a24462ad6196f4a4491748a69 Mon Sep 17 00:00:00 2001
From: =?UTF-8?q?Niccol=C3=B2=20Venerandi?= <niccolo@venerandi.com>
Date: Tue, 24 Nov 2026 22:21:10 +0100
Subject: [PATCH] applet: open the default gateway in the browser when clicking
 it

The default gateway in the connection details was plain text, so
opening the router's page meant copying it into a browser. Details can
now carry a link, and the gateway is shown as one that opens it.

BUG: 468990
---
 applet/DetailsText.qml                        | 21 +++++++--
 libs/editor/connectiondetails.cpp             | 46 ++++++++++++-------
 libs/editor/connectiondetails.h               | 12 +++--
 .../settings/connectionstatuswidget.cpp       |  2 +-
 libs/models/connectiondetailsmodel.cpp        |  7 ++-
 libs/models/connectiondetailsmodel.h          |  5 +-
 6 files changed, 66 insertions(+), 27 deletions(-)

diff --git a/applet/DetailsText.qml b/applet/DetailsText.qml
index 8c880d347..e2301c859 100644
--- a/applet/DetailsText.qml
+++ b/applet/DetailsText.qml
@@ -63,6 +63,9 @@ MouseArea {
                 required property string sectionTitle
                 required property string detailLabel
                 required property string detailValue
+                required property url detailUrl
+
+                readonly property bool hasUrl: detailUrl.toString() !== ""

                 Layout.fillWidth: true
                 Layout.columnSpan: 2
@@ -120,13 +123,25 @@ MouseArea {
                     horizontalAlignment: Text.AlignLeft
                     text: delegateItem.detailValue
                     textFormat: Text.PlainText
+                    color: delegateItem.hasUrl ? Kirigami.Theme.linkColor : Kirigami.Theme.textColor
                     opacity: 1

                     MouseArea {
-                        anchors.fill: parent
-                        acceptedButtons: Qt.RightButton
+                        anchors.left: parent.left
+                        anchors.top: parent.top
+                        anchors.bottom: parent.bottom
+                        width: delegateItem.hasUrl ? Math.min(parent.width, detailValueItem.contentWidth) : parent.width
+                        acceptedButtons: delegateItem.hasUrl ? Qt.LeftButton | Qt.RightButton : Qt.RightButton
+                        cursorShape: delegateItem.hasUrl ? Qt.PointingHandCursor : Qt.ArrowCursor
                         onPressed: mouse => {
-                            contextMenu.show(this, detailValueItem.text, mouse.x, mouse.y);
+                            if (mouse.button === Qt.RightButton) {
+                                contextMenu.show(this, detailValueItem.text, mouse.x, mouse.y);
+                            }
+                        }
+                        onClicked: mouse => {
+                            if (mouse.button === Qt.LeftButton) {
+                                Qt.openUrlExternally(delegateItem.detailUrl);
+                            }
                         }
                     }
                 }
